const body = $input.first().json.body || $input.first().json;
const cliente = body.cliente || {};
const negocio = body.negocio || {};
const payload = body.payload || {};
const tipo = body.tipo_evento || 'sello_confirmado';

// Verificar consentimiento y ausencia de baja
const optInWa = Boolean(cliente.consentimiento_whatsapp) && !Boolean(cliente.baja_whatsapp);
const rawPhone = String(cliente.celular || payload.celular || '').replace(/\D/g, '');
const numeroWa = rawPhone.length === 9 ? `51${rawPhone}` : rawPhone;

// Calcular hora actual en America/Lima (UTC-5)
const nowLima = new Date(new Date().toLocaleString('en-US', { timeZone: 'America/Lima' }));
const mins = nowLima.getHours() * 60 + nowLima.getMinutes();
const dentroHorario = mins >= 9 * 60 && mins <= 20 * 60;

// Jitter anti-ban aleatorio (8 a 25 segundos)
const delaySegundos = Math.floor(Math.random() * 18) + 8;

const nombre = cliente.nombre || payload.nombre || 'Amig@';
const sellos = payload.sellos_actuales ?? 1;
const falta = payload.falta ?? 1;
const premio = payload.premio || negocio.nombre_premio || 'Café de Especialidad gratis';
const url = body.cartilla_url || 'https://oliviacafe.pe/c/olivia';

const plantillas = {
  cliente_registrado: `¡Hola ${nombre}! Bienvenido a Olivia Café ☕ Ya tienes 1 sello de bienvenida. Mira tu cartilla aquí: ${url}. Responde BAJA para no recibir más.`,
  sello_confirmado: `¡${nombre}, te falta solo ${falta} sello para tu ${premio} gratis en Olivia Café!`,
  premio_listo: `🎉 ¡Felicidades, ${nombre}! Completaste ${sellos} sellos. Tu ${premio} te espera en Olivia Café. Muestra tu QR en caja. Responde BAJA para no recibir más.`,
  cumpleanos_hoy: `🎂 ¡Feliz cumpleaños, ${nombre}! Esta semana Olivia Café te regala una porción de tarta artesanal gratis al mostrar tu cartilla: ${url}. Responde BAJA para no recibir más.`,
  reactivacion_inactivos: `¡Te extrañamos, ${nombre}! Llevas ${sellos} sellos en tu cartilla de Olivia Café. Vuelve esta semana por tu café favorito. Responde BAJA para no recibir más.`,
  encuesta_visita: `Hola ${nombre}, ¿cómo estuvo tu café hoy en Olivia Café? Responde del 1 al 5 ⭐. Responde BAJA para no recibir más.`,
  campana_masiva: payload.mensaje || `¡Novedad en Olivia Café! Mira tu beneficio activo en ${url}. Responde BAJA para no recibir más.`
};

return [{
  json: {
    outbox_id: body.outbox_id || null,
    negocio_id: body.negocio_id,
    cliente_id: cliente.id || payload.cliente_id || null,
    tipo_evento: tipo,
    instance_name: negocio.evolution_instance_name || 'olivia-lima-wa',
    numero_wa: numeroWa,
    puede_enviar_wa: optInWa && Boolean(numeroWa) && dentroHorario,
    dentro_horario: dentroHorario,
    delay_segundos: delaySegundos,
    mensaje: body.mensaje || plantillas[tipo] || plantillas.sello_confirmado
  }
}];
